// CALLEE: ValidateLayout (lines 141-161)
private static void ValidateLayout(object[] result, Block block)
{
    Validate(block, result[0], "pubkey", ExecutionRequestExtensions.PublicKeySize);  // 48
    Validate(block, result[1], "withdrawalCredentials", ExecutionRequestExtensions.WithdrawalCredentialsSize);  // 32
    Validate(block, result[2], "amount", ExecutionRequestExtensions.AmountSize);  // 8
    Validate(block, result[3], "signature", ExecutionRequestExtensions.SignatureSize);  // 96
    Validate(block, result[4], "index", ExecutionRequestExtensions.IndexSize);  // 8
    // Total: 48+32+8+96+8 = 192 bytes (not 576 - that would be ABI-encoded with offsets)
}

// PRIMARY: src/Nethermind/Nethermind.Core/ExecutionRequest/ExecutionRequestExtensions.cs:CalculateHashFromFlatEncodedRequests (lines 33-50)
[SkipLocalsInit]
public static Hash256 CalculateHashFromFlatEncodedRequests(byte[][]? flatEncodedRequests)
{
    if (flatEncodedRequests is null)
    {
        throw new ArgumentException("Flat encoded requests must be an array");
    }
    using ArrayPoolList<byte> concatenatedHashes = new(Hash256.Size * MaxRequestsCount);
    foreach (byte[] requests in flatEncodedRequests)
    {
        if (requests.Length <= 1) continue;
        concatenatedHashes.AddRange(SHA256.HashData(requests));
    }
    // Compute sha256 of the concatenated hashes
    return new Hash256(SHA256.HashData(concatenatedHashes.UnsafeGetInternalArray().AsSpan(0, concatenatedHashes.Count)));
}
